// Existing, working helper. Preserve its exported behavior.
export function normalizeSegments(input){
  if(typeof input!=='string')throw Error('invalid path');
  const segments=[];
  for(const part of input.split('/')){
    if(part===''||part==='.')continue;
    if(part==='..'){segments.pop();continue;}
    segments.push(part);
  }
  return segments;
}

import{readFileSync,realpathSync}from'node:fs';
import{isAbsolute,resolve}from'node:path';
import{fileURLToPath,pathToFileURL}from'node:url';

// Lexical containment: resolves candidate against root (without touching the
// filesystem) and reports whether the normalized result stays inside root.
export function resolveWithin(root,candidate){
  if(typeof root!=='string'||root.length===0||root.includes('\0')){
    throw new Error('root must be a nonempty string containing no NUL');
  }
  if(typeof candidate!=='string'||candidate.length===0||candidate.includes('\0')){
    throw new Error('candidate must be a nonempty string containing no NUL');
  }
  if(!root.startsWith('/')){
    throw new Error('root must start with /');
  }
  const rootSegments=normalizeSegments(root);
  const target=candidate.startsWith('/')?candidate:root+'/'+candidate;
  const segments=normalizeSegments(target);
  const resolved=segments.length===0?'/':'/'+segments.join('/');
  const inside=rootSegments.length<=segments.length&&
    rootSegments.every((segment,index)=>segments[index]===segment);
  const relative=inside?segments.slice(rootSegments.length).join('/'):null;
  return {inside,resolved,relative};
}

function errorMessage(err){
  return err instanceof Error&&err.message!==''?err.message:String(err);
}

function fail(message){
  process.stderr.write(`path-scope: ${message}\n`);
  process.exitCode=2;
}

function runCli(){
  const args=process.argv.slice(2);
  if(args.length!==1){
    fail('expected exactly one argument: INPUT_JSON_FILE');
    return;
  }
  let data;
  try{
    data=JSON.parse(readFileSync(args[0],'utf8'));
  }catch(err){
    fail(`cannot read or parse input file: ${errorMessage(err)}`);
    return;
  }
  if(typeof data!=='object'||data===null||Array.isArray(data)){
    fail('input JSON must be a non-null, non-array object with root and candidate');
    return;
  }
  try{
    const result=resolveWithin(data.root,data.candidate);
    process.stdout.write(`${JSON.stringify(result)}\n`);
  }catch(err){
    fail(errorMessage(err));
  }
}

function isCliEntry(){
  const entry=process.argv[1];
  if(!entry)return false;
  const entryPath=isAbsolute(entry)?entry:resolve(process.cwd(),entry);
  try{
    if(pathToFileURL(entryPath).href===import.meta.url)return true;
    return realpathSync(entryPath)===realpathSync(fileURLToPath(import.meta.url));
  }catch{
    return false;
  }
}

if(isCliEntry())runCli();

import test from 'node:test';
import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {mkdtempSync,rmSync,writeFileSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {resolveWithin} from '../path-scope.js';

const scriptPath=fileURLToPath(new URL('../path-scope.js',import.meta.url));

test('spec example: relative candidate climbing into the root',()=>{
  assert.deepEqual(resolveWithin('/srv/ws','../ws/sub/../file.txt'),
    {inside:true,resolved:'/srv/ws/file.txt',relative:'file.txt'});
});

test('spec example: absolute candidate with a shared textual prefix is outside',()=>{
  assert.deepEqual(resolveWithin('/srv/ws','/srv/wsx'),
    {inside:false,resolved:'/srv/wsx',relative:null});
});

test('same location reports an empty relative path',()=>{
  assert.deepEqual(resolveWithin('/srv/ws','.'),
    {inside:true,resolved:'/srv/ws',relative:''});
  assert.deepEqual(resolveWithin('/srv/ws','/srv/ws'),
    {inside:true,resolved:'/srv/ws',relative:''});
  assert.deepEqual(resolveWithin('/srv/ws/','/srv/ws/'),
    {inside:true,resolved:'/srv/ws',relative:''});
});

test('absolute candidates inside the root resolve to a relative path',()=>{
  assert.deepEqual(resolveWithin('/srv/ws','/srv/ws/deep/file'),
    {inside:true,resolved:'/srv/ws/deep/file',relative:'deep/file'});
  assert.deepEqual(resolveWithin('/srv/ws','/srv/ws'),
    {inside:true,resolved:'/srv/ws',relative:''});
});

test('the filesystem root contains everything and cannot be climbed above',()=>{
  assert.deepEqual(resolveWithin('/','a/b'),
    {inside:true,resolved:'/a/b',relative:'a/b'});
  assert.deepEqual(resolveWithin('/','/'),
    {inside:true,resolved:'/',relative:''});
  assert.deepEqual(resolveWithin('/','../../x'),
    {inside:true,resolved:'/x',relative:'x'});
  assert.deepEqual(resolveWithin('/a/b','../../..'),
    {inside:false,resolved:'/',relative:null});
});

test('.. segments can climb out of the root',()=>{
  assert.deepEqual(resolveWithin('/a/b','../b'),
    {inside:false,resolved:'/b',relative:null});
  assert.deepEqual(resolveWithin('/a/b','../../a/b/x'),
    {inside:true,resolved:'/a/b/x',relative:'x'});
  assert.deepEqual(resolveWithin('/a/b','..'),
    {inside:false,resolved:'/a',relative:null});
});

test('dot and dotdot lookalikes and hidden names are ordinary segments',()=>{
  assert.deepEqual(resolveWithin('/a','..foo/.../.hidden'),
    {inside:true,resolved:'/a/..foo/.../.hidden',relative:'..foo/.../.hidden'});
  assert.deepEqual(resolveWithin('/a','..'),
    {inside:false,resolved:'/',relative:null});
});

test('backslash is an ordinary character, never a separator',()=>{
  assert.deepEqual(resolveWithin('/a','x\\y'),
    {inside:true,resolved:'/a/x\\y',relative:'x\\y'});
  assert.deepEqual(resolveWithin('/a\\b','c'),
    {inside:true,resolved:'/a\\b/c',relative:'c'});
});

test('trailing slashes and redundant separators normalize away',()=>{
  assert.deepEqual(resolveWithin('/a/','b/'),
    {inside:true,resolved:'/a/b',relative:'b'});
  assert.deepEqual(resolveWithin('/a//b/./c','//x/./y/../z'),
    {inside:true,resolved:'/a/b/z',relative:'z'});
});

test('the result object contains exactly inside, resolved and relative',()=>{
  const result=resolveWithin('/a','b');
  assert.deepEqual(Object.keys(result),['inside','resolved','relative']);
});

test('invalid inputs throw an Error before resolving',()=>{
  for(const [root,candidate] of[
    ['a','b'],
    ['','x'],
    ['/a',''],
    ['/\0a','x'],
    ['/a','x\0y'],
    [5,'x'],
    [null,'x'],
    ['/a',null],
    ['/a',42],
    [NaN,'x'],
  ]){
    assert.throws(()=>resolveWithin(root,candidate),Error);
  }
});

test('inputs are not mutated',()=>{
  const root='/srv/ws';
  const candidate='../ws/sub/../file.txt';
  resolveWithin(root,candidate);
  assert.equal(root,'/srv/ws');
  assert.equal(candidate,'../ws/sub/../file.txt');
});

function runCli(args){
  return spawnSync(process.execPath,[scriptPath,...args],{encoding:'utf8'});
}

function withTempInput(write,onInput){
  const dir=mkdtempSync(join(tmpdir(),'path-scope-'));
  const file=join(dir,'input.json');
  try{
    if(write!==undefined)writeFileSync(file,write);
    return onInput(file,dir);
  }finally{
    rmSync(dir,{recursive:true,force:true});
  }
}

test('cli prints the API result and exits 0',()=>{
  withTempInput(
    JSON.stringify({root:'/srv/ws',candidate:'../ws/sub/../file.txt',extra:'ignored',n:1}),
    (file)=>{
      const r=runCli([file]);
      assert.equal(r.status,0);
      assert.equal(r.stderr,'');
      assert.equal(r.stdout,
        JSON.stringify({inside:true,resolved:'/srv/ws/file.txt',relative:'file.txt'})+'\n');
    });
});

test('cli exits 2 with stderr and no stdout on bad argument counts',()=>{
  for(const args of[[],['a','b']]){
    const r=runCli(args);
    assert.equal(r.status,2);
    assert.ok(r.stderr.length>0);
    assert.equal(r.stdout,'');
  }
});

test('cli exits 2 when the input file is missing or is a directory',()=>{
  const r=runCli([join(tmpdir(),'path-scope-nope.json')]);
  assert.equal(r.status,2);
  assert.ok(r.stderr.length>0);
  assert.equal(r.stdout,'');
  withTempInput(undefined,(file,dir)=>{
    const rd=runCli([dir]);
    assert.equal(rd.status,2);
    assert.ok(rd.stderr.length>0);
    assert.equal(rd.stdout,'');
  });
});

test('cli exits 2 for invalid JSON shapes and API input',()=>{
  const bad=[
    '{oops',
    '[1,2]',
    'null',
    '"x"',
    '42',
    '{"root":"/a"}',
    '{"root":"a","candidate":"b"}',
    '{"root":"/a","candidate":""}',
    '{"root":7,"candidate":"b"}',
  ];
  for(const text of bad){
    withTempInput(text,(file)=>{
      const r=runCli([file]);
      assert.equal(r.status,2);
      assert.ok(r.stderr.length>0);
      assert.equal(r.stdout,'');
    });
  }
});

test('importing the module does not run the CLI',()=>{
  const r=spawnSync(process.execPath,
    ['-e',`import(${JSON.stringify(scriptPath)}).then(m=>{if(!m.resolveWithin)process.exit(1)})`],
    {encoding:'utf8'});
  assert.equal(r.status,0);
  assert.equal(r.stdout,'');
  assert.equal(r.stderr,'');
});

